package com.ojjudge.cache;

/**
 * 缓存名称常量。
 *
 * <p>集中在这里是为了让"缓存了哪些东西、写操作要清哪些"一眼可查 ——
 * 缓存最容易出的错不是没命中，而是<b>漏了失效点</b>：
 * 某个写路径忘了清，用户就会一直看到旧数据，而且这种问题很难复现。
 */
public interface CacheNames {

    /**
     * 全站已用过的标签（含使用次数）。
     *
     * <p>清这个缓存的时机：任何会改动标签的写操作（题目新增 / 编辑 / 删除）。
     */
    String TAGS = "tags";

    /**
     * 单道题的脱敏详情（{@code QuestionVO}），按题目 id 缓存。
     *
     * <p>清这个缓存的时机：题目被编辑 / 删除，以及
     * <b>提交次数或通过人数发生变化时</b>（{@code submit_num} / {@code accepted_num}
     * 就在这个 VO 里，判题回写统计时必须清，否则通过率永远显示旧值）。
     */
    String QUESTION = "question";

    /**
     * 题目列表的"骨架"：某一组查询条件下，总数是多少、这一页有哪些 id。
     * key 就是查询条件本身。
     *
     * <p><b>为什么要把它和 {@link #QUESTION} 分开</b>：这是整个缓存设计的关键。
     * 一份查询结果里其实混着两类数据 ——
     * <ul>
     *   <li>"哪些题、共几条"：只有题目增删改才会变（低频）</li>
     *   <li>"每题的通过率"：每完成一次判题就会变（高频）</li>
     * </ul>
     * 放在一起缓存，判题一回写就得整片清空，命中率直接归零。
     * 拆开之后，判题回写<b>只清 {@link #QUESTION} 那一条</b>，
     * 这个骨架缓存可以稳稳地活到 TTL 到期。
     *
     * <p>清这个缓存的时机：<b>只有</b>题目新增 / 编辑 / 删除。判题回写清它。
     */
    String QUESTION_IDS = "question-ids";
}
